<?php
require __DIR__.'/_common.php';
try{$token=token_from_query();if($token==='')respond(['error'=>'Missing token.'],400);$pdo=db();$s=$pdo->prepare('SELECT id,order_no,customer_name,customer_mobile,total_amount,status,created_at,delivered_at FROM orders WHERE qr_token=?');$s->execute([$token]);$o=$s->fetch();if(!$o)respond(['error'=>'Order not found / invalid QR.'],404);$si=$pdo->prepare('SELECT item_name,quantity,rate,amount FROM order_items WHERE order_id=? ORDER BY id');$si->execute([$o['id']]);$items=[];foreach($si as $i)$items[]=['name'=>$i['item_name'],'qty'=>(float)$i['quantity'],'rate'=>(float)$i['rate'],'amount'=>(float)$i['amount']];respond(['orderNo'=>$o['order_no'],'customerName'=>$o['customer_name'],'customerMobile'=>$o['customer_mobile'],'total'=>(float)$o['total_amount'],'status'=>$o['status'],'createdAt'=>$o['created_at'],'deliveredAt'=>$o['delivered_at'],'items'=>$items]);}catch(Throwable $e){error_log($e);respond(['error'=>'Unable to retrieve order.'],500);}
